31	// Deals with any settings in the "User Experience" setting sub-screen
32	class ExperienceTweaks extends Forwarder {
33	    /**
34	     * InputType that behaves as if the consuming IME is a standard-obeying
35	     * soft-keyboard
36	     * <p>
37	     * *Auto Complete* means "we're handling auto-completion ourselves". Then
38	     * we ignore whatever the IME thinks we should display.
39	     */
40	    private final static int INPUT_TYPE_STANDARD = InputType.TYPE_CLASS_TEXT
41	            | InputType.TYPE_TEXT_FLAG_AUTO_COMPLETE
42	            | InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS;
43	    /**
44	     * InputType that behaves as if the consuming IME is SwiftKey
45	     * <p>
46	     * *Visible Password* fields will break many non-Latin IMEs and may show
47	     * unexpected behaviour in numerous ways. (#454, #517)
48	     */
49	    private final static int INPUT_TYPE_WORKAROUND = InputType.TYPE_TEXT_VARIATION_VISIBLE_PASSWORD
50	            | InputType.TYPE_TEXT_FLAG_AUTO_CORRECT;
51	
52	    private final Runnable displayKeyboardRunnable = mainActivity::showKeyboard;
53	
54	    private View mainEmptyView;
55	    private final GestureDetector gd;
56	
57	    @SuppressLint("SourceLockedOrientationActivity")
58	    ExperienceTweaks(final MainActivity mainActivity) {
59	        super(mainActivity);
60	
61	        // Lock launcher into portrait mode
62	        // Do it here (before initializing the view in onCreate) to make the transition as smooth as possible
63	        if (prefs.getBoolean("force-portrait", true)) {
64	            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.JELLY_BEAN_MR2) {
65	                mainActivity.setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_USER_PORTRAIT);
66	            } else {
67	                mainActivity.setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_PORTRAIT);
68	            }
69	        } else {
70	            mainActivity.setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_USER);
71	        }
72	
73	        gd = new GestureDetector(mainActivity, new GestureDetector.SimpleOnGestureListener() {
74	            @Override
75	            public boolean onSingleTapUp(MotionEvent e) {
76	                // Double tap disabled: display history directly
77	                if(!prefs.getBoolean("double-tap", false)) {
78	                    if (prefs.getBoolean("history-onclick", false)) {
79	                        doAction("display-history");
80	                    }
81	                }
82	                return super.onSingleTapUp(e);
83	            }
84	
85	            @Override
86	            public boolean onSingleTapConfirmed(MotionEvent e) {
87	                // Double tap enabled: wait to confirm this is indeed a single tap, not a double tap
88	                if(prefs.getBoolean("double-tap", false)) {
89	                    if (prefs.getBoolean("history-onclick", false)) {
90	                        doAction("display-history");
91	                    }
92	                }
93	
94	                return super.onSingleTapConfirmed(e);
95	            }
96	
97	            @Override
98	            public boolean onDoubleTap(MotionEvent e) {
99	                if (Build.VERSION.SDK_INT < Build.VERSION_CODES.P) {
100	                    return super.onDoubleTap(e);
101	                }
102	                if(!prefs.getBoolean("double-tap", false)) {
103	                    return super.onDoubleTap(e);
104	                }
105	
106	                if (isAccessibilityServiceEnabled(mainActivity)) {
107	                    Intent intent = new Intent(LockAccessibilityService.ACTION_LOCK, null, mainActivity, LockAccessibilityService.class);
108	                    mainActivity.startService(intent);
109	                } else {
110	                    AlertDialog.Builder builder = new AlertDialog.Builder(mainActivity);
111	                    builder.setMessage(R.string.enable_double_tap_to_lock);
112	
113	                    builder.setPositiveButton(android.R.string.ok, (dialog, which) -> {
114	                        Intent intent = new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS);
115	                        intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
116	                        mainActivity.startActivity(intent);
117	                    });
118	
119	                    builder.setNegativeButton(android.R.string.cancel, (dialog, which) -> {
120	                        dialog.dismiss();
121	                    });
122	
123	                    AlertDialog alert = builder.create();
124	                    alert.show();
125	                }
126	                return super.onDoubleTap(e);
127	            }
128	
129	            @Override
130	            public boolean onFling(MotionEvent e1, MotionEvent e2, float velocityX, float velocityY) {
131	                float directionY = e2.getY() - e1.getY();
132	                float directionX = e2.getX() - e1.getX();
133	                if (Math.abs(directionX) > Math.abs(directionY)) {
134	                    return false;
135	                }
136	                if (directionY > 0) {
137	                    doAction(prefs.getString("gesture-down", "display-notifications"));
138	                } else {
139	                    doAction(prefs.getString("gesture-up", "display-keyboard"));
140	                }
141	                return true;
142	            }
143	
144	            private void doAction(String action) {
145	                switch (action) {
146	                    case "display-notifications":
147	                        displayNotificationDrawer();
148	                        break;
149	                    case "display-keyboard":
150	                        mainActivity.showKeyboard();
151	                        break;
152	                    case "display-apps":
153	                        if (mainActivity.isViewingSearchResults()) {
154	                            mainActivity.displayKissBar(true);
155	                        }
156	                        break;
157	                    case "display-history":
158	                        // if minimalistic mode is enabled,
159	                        if (isMinimalisticModeEnabled()) {
160	                            // and we're currently in minimalistic mode with no results,
161	                            // and we're not looking at the app list
162	                            if (mainActivity.isViewingSearchResults() && mainActivity.searchEditText.getText().toString().isEmpty()) {
163	                                if (mainActivity.list.getAdapter() == null || mainActivity.list.getAdapter().isEmpty()) {
164	                                    mainActivity.runTask(new HistorySearcher(mainActivity));
165	                                    mainActivity.clearButton.setVisibility(View.VISIBLE);
166	                                    mainActivity.menuButton.setVisibility(View.INVISIBLE);
167	                                }
168	                            }
169	                        }
170	
171	                        if (isMinimalisticModeEnabledForFavorites()) {
172	                            mainActivity.favoritesBar.setVisibility(View.VISIBLE);
173	                        }
174	                        break;
175	                }
176	            }
177	        });
178	    }
