184	    void onResume() {
185	        adjustInputType();
186	
187	        // Activity manifest specifies stateAlwaysHidden as windowSoftInputMode
188	        // so the keyboard will be hidden by default
189	        // we may want to display it if the setting is set
190	        if (isKeyboardOnStartEnabled()) {
191	            // Display keyboard
192	            mainActivity.showKeyboard();
193	
194	            new Handler().postDelayed(displayKeyboardRunnable, 10);
195	            // For some weird reasons, keyboard may be hidden by the system
196	            // So we have to run this multiple time at different time
197	            // See https://github.com/Neamar/KISS/issues/119
198	            new Handler().postDelayed(displayKeyboardRunnable, 100);
199	            new Handler().postDelayed(displayKeyboardRunnable, 500);
200	        } else {
201	            // Not used (thanks windowSoftInputMode)
202	            // unless coming back from KISS settings
203	            mainActivity.hideKeyboard();
204	        }
205	
206	        if (isMinimalisticModeEnabled()) {
207	            mainEmptyView.setVisibility(View.GONE);
208	
209	            mainActivity.list.setVerticalScrollBarEnabled(false);
210	            mainActivity.searchEditText.setHint("");
211	        }
212	        if (prefs.getBoolean("pref-hide-circle", false)) {
213	            ((ImageView) mainActivity.launcherButton).setImageBitmap(null);
214	            ((ImageView) mainActivity.menuButton).setImageBitmap(null);
215	        }
216	    }
