230	        if (isMinimalisticModeEnabledForFavorites() && !display) {
231	            mainActivity.favoritesBar.setVisibility(View.GONE);
232	        }
233	
234	        if (!display && isKeyboardOnStartEnabled()) {
235	            // Display keyboard
236	            mainActivity.showKeyboard();
237	        }
238	    }
