240	    void updateSearchRecords(boolean isRefresh, String query) {
241	        if (query.isEmpty()) {
242	            if (isMinimalisticModeEnabled()) {
243	                mainActivity.runTask(new NullSearcher(mainActivity));
244	                // By default, help text is displayed -- not in minimalistic mode.
245	                mainEmptyView.setVisibility(View.GONE);
246	
247	                if (isMinimalisticModeEnabledForFavorites()) {
248	                    mainActivity.favoritesBar.setVisibility(View.GONE);
249	                }
250	            } else {
251	                Searcher searcher = new HistorySearcher(mainActivity);
252	                searcher.setRefresh(isRefresh);
253	                mainActivity.runTask(searcher);
254	            }
255	        }
256	    }
