258	    // Ensure the keyboard uses the right input method
259	    private void adjustInputType() {
260	        int currentInputType = mainActivity.searchEditText.getInputType();
261	        int requiredInputType;
262	
263	        if (isSuggestionsEnabled()) {
264	            requiredInputType = InputType.TYPE_CLASS_TEXT;
265	        } else {
266	            if (isNonCompliantKeyboard()) {
267	                requiredInputType = INPUT_TYPE_WORKAROUND;
268	            } else {
269	                requiredInputType = INPUT_TYPE_STANDARD;
270	            }
271	        }
272	        if (currentInputType != requiredInputType) {
273	            mainActivity.searchEditText.setInputType(requiredInputType);
274	        }
275	    }
