304	    private boolean isMinimalisticModeEnabled() {
305	        return prefs.getBoolean("history-hide", false);
306	    }
307	
308	    private boolean isMinimalisticModeEnabledForFavorites() {
309	        return prefs.getBoolean("history-hide", false) && prefs.getBoolean("favorites-hide", false) && prefs.getBoolean("enable-favorites-bar", true);
310	    }
