312	    /**
313	     * Should we force the keyboard not to display suggestions?
314	     * (swiftkey is broken, see https://github.com/Neamar/KISS/issues/44)
315	     * (same for flesky: https://github.com/Neamar/KISS/issues/1263)
316	     */
317	    private boolean isNonCompliantKeyboard() {
318	        String currentKeyboard = Settings.Secure.getString(mainActivity.getContentResolver(), Settings.Secure.DEFAULT_INPUT_METHOD).toLowerCase();
319	        return currentKeyboard.contains("swiftkey") || currentKeyboard.contains("flesky");
320	    }
321	
322	    /**
323	     * Should the keyboard be displayed by default?
324	     */
325	    private boolean isKeyboardOnStartEnabled() {
326	        return prefs.getBoolean("display-keyboard", false);
327	    }
328	
329	    /**
330	     * Should the keyboard autocomplete and suggest options
331	     */
332	    private boolean isSuggestionsEnabled() {
333	        return prefs.getBoolean("enable-suggestions-keyboard", false);
334	    }
335	
336	    /**
337	     * Are we allowed to run our AccessibilityService?
338	     */
339	    private boolean isAccessibilityServiceEnabled(Context context) {
340	        AccessibilityManager am = (AccessibilityManager) context.getSystemService(Context.ACCESSIBILITY_SERVICE);
341	        if (am == null) {
342	            return false;
343	        }
344	
345	        List<AccessibilityServiceInfo> enabledServices = am.getEnabledAccessibilityServiceList(AccessibilityServiceInfo.FEEDBACK_ALL_MASK);
346	
347	
348	        for (AccessibilityServiceInfo enabledService : enabledServices) {
349	            ServiceInfo enabledServiceInfo = enabledService.getResolveInfo().serviceInfo;
350	            if (enabledServiceInfo.packageName.equals(context.getPackageName()) && enabledServiceInfo.name.equals(LockAccessibilityService.class.getName()))
351	                return true;
352	        }
353	
354	        return false;
355	    }
356	}
