231	    @SuppressLint("ClickableViewAccessibility")
232	    public boolean onTouch(View view, MotionEvent motionEvent) {
233	        // How long to hold your finger in place to trigger the app menu.
234	        final int LONG_PRESS_DELAY = 250;
235	
236	        if (motionEvent.getAction() == MotionEvent.ACTION_DOWN) {
237	            startTime = motionEvent.getEventTime();
238	            return false;
239	        }
240	        // No need to do any extra work while dragging
241	        if (isDragging) {
242	            return false;
243	        }
244	
245	        long holdTime = motionEvent.getEventTime() - startTime;
246	
247	        if (holdTime > LONG_PRESS_DELAY) {
248	            // Long press, either drag or context menu
249	            int intCurrentY = Math.round(motionEvent.getY());
250	            int intCurrentX = Math.round(motionEvent.getX());
251	            int intStartY = motionEvent.getHistorySize() > 0 ? Math.round(motionEvent.getHistoricalY(0)) : intCurrentY;
252	            int intStartX = motionEvent.getHistorySize() > 0 ? Math.round(motionEvent.getHistoricalX(0)) : intCurrentX;
253	
254	            // How much you need to move your finger to be considered "moving"
255	            int MOVE_SENSITIVITY = 8;
256	            boolean hasMoved = (Math.abs(intCurrentX - intStartX) > MOVE_SENSITIVITY) || (Math.abs(intCurrentY - intStartY) > MOVE_SENSITIVITY);
257	
258	            if (hasMoved && mDragEnabled && !isDragging) {
259	                view.performHapticFeedback(HapticFeedbackConstants.LONG_PRESS);
260	
261	                mDragEnabled = false;
262	                mainActivity.dismissPopup();
263	                mainActivity.closeContextMenu();
264	
265	                mainActivity.favoritesBar.setOnDragListener(this);
266	                View.DragShadowBuilder shadowBuilder = new View.DragShadowBuilder(view);
267	                view.setVisibility(View.INVISIBLE);
268	                isDragging = true;
269	                view.cancelLongPress();
270	                view.startDrag(null, shadowBuilder, view, 0);
271	                return true;
272	            }
273	        }
274	
275	        return false;
276	    }
