278	    @Override
279	    public boolean onDrag(View targetView, final DragEvent event) {
280	        final View draggedView = (View) event.getLocalState();
281	
282	        switch (event.getAction()) {
283	            case DragEvent.ACTION_DRAG_STARTED:
284	                return targetView instanceof LinearLayout;
285	            case DragEvent.ACTION_DRAG_ENTERED:
286	                return isDragging;
287	            case DragEvent.ACTION_DRAG_LOCATION:
288	                ViewGroup bar = ((ViewGroup) targetView);
289	                float x = event.getX();
290	                int width = targetView.getWidth();
291	
292	                int currentPos = (int) (favCount * x / width);
293	
294	                View currentChildAtPos = bar.getChildAt(currentPos);
295	                if (currentChildAtPos != draggedView) {
296	                    // Do not update the ViewGroup during the event dispatch, older Androids will crash
297	                    // See #1419
298	                    bar.removeView(draggedView);
299	                    try {
300	                        bar.addView(draggedView, currentPos);
301	                    } catch (IllegalStateException e) {
302	                        // In some situations,
303	                        // removeView() somehow fails (this especially happens if you start the drag and immediately moves to the left or right)
304	                        // and we can't add the children back, because it still has a parent. In this case, do nothing, this should fix itself on the next iteration.
305	                        // This is very likely caused by animateLayoutChange, since disabling the property fixes the issue... but also removes all animation.
306	                        potentialNewIndex = -1;
307	                        return false;
308	                    }
309	                }
310	
311	                potentialNewIndex = currentPos;
312	                return true;
313	            case DragEvent.ACTION_DROP:
314	                // Accept the drop, will be followed by ACTION_DRAG_ENDED
315	                return isDragging;
316	            case DragEvent.ACTION_DRAG_ENDED:
317	                final ViewHolder draggedApp = (ViewHolder) draggedView.getTag();
318	                int newIndex = potentialNewIndex;
319	
320	                draggedView.post(() -> {
321	                    // Reset dragging to what it should be
322	                    // Need to be posted to avoid updating the ViewGroup during the event dispatch, older Androids will crash otherwise
323	                    // See #1419
324	                    draggedView.setVisibility(View.VISIBLE);
325	
326	                    try {
327	                        if (newIndex == -1) {
328	                            // Sometimes we don't trigger onDrag over another app, in which case just drop.
329	                            Log.w(TAG, "Wasn't dragged over a favorite, returning app to starting position");
330	                            // We still need to refresh our favorites, in case one was removed and never added back (see IllegalStateException above)
331	                            mainActivity.onFavoriteChange();
332	                        } else {
333	                            // Signals to a View that the drag and drop operation has concluded.
334	                            // If event result is set, this means the dragged view was dropped in target
335	                            if (event.getResult()) {
336	                                KissApplication.getApplication(mainActivity).getDataHandler().setFavoritePosition(mainActivity, draggedApp.result.getPojoId(), newIndex);
337	                            }
338	                        }
339	                    } catch (IllegalStateException e) {
340	                        // An animation was running. Retry later
341	                        // (to trigger: long press a favorite while already moving your finger a little, release as soon as you get haptic feedback)
342	                        draggedView.postDelayed(mainActivity::onFavoriteChange, 300);
343	                    }
344	                });
345	
346	                mDragEnabled = favCount > 1;
347	                potentialNewIndex = -1;
348	                isDragging = false;
349	                return true;
350	            default:
351	                break;
352	        }
353	        return isDragging;
354	    }
